package org.apache.commons.text;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringSubstitutor_ESTest_test41 extends StringSubstitutor_ESTest_scaffolding {

    /**
     * Verifies that {@link StringSubstitutor#replaceIn(StringBuilder)} collapses the
     * escape sequence "$$" into a single "$" in place.
     *
     * <p>The source builder is assembled to contain an escaped dollar sign ("$$")
     * followed by an empty variable reference ("${}"). Because an actual change is
     * made (the escape is collapsed), {@code replaceIn} must return {@code true}
     * and the builder must be updated to hold the collapsed text. The embedded NUL
     * ('�') characters are carried through unchanged.</p>
     */
    @Test(timeout = 4000)
    public void replaceInCollapsesEscapedDollarSignInStringBuilder() throws Throwable {
        StringSubstitutor stringSubstitutor = new StringSubstitutor();

        // Build the source: "}" + four NUL chars + "$" + "${" + "}".
        char[] nullsThenDollar = new char[5];
        nullsThenDollar[4] = '$';

        StringBuilder source = new StringBuilder("}");
        source.append(nullsThenDollar);   // "}����$"
        source.append((CharSequence) "${");
        source.append("}");               // "}����$${}"

        // Appending the builder to itself duplicates its current content.
        source.append((Object) source);   // "}����$${}}����$${}"

        boolean altered = stringSubstitutor.replaceIn(source);

        // Each "$$" escape is collapsed to a single "$"; the empty "${}" reference is left untouched.
        assertEquals("}����${}}����${}", source.toString());
        assertTrue(altered);
    }
}
